describe('Checkout Form Mobile Vertical Stacking', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should stack checkout form fields vertically on mobile viewport', () => {
    // Intercept API calls
    cy.intercept('POST', '/api/checkout').as('checkoutSubmit');

    // Set mobile viewport
    cy.viewport('iphone-x');

    // Verify form fields are visible
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="first-name-input"]').should('be.visible');
    cy.get('[data-testid="last-name-input"]').should('be.visible');
    cy.get('[data-testid="address-input"]').should('be.visible');
    cy.get('[data-testid="phone-input"]').should('be.visible');
    cy.get('[data-testid="card-number-input"]').should('be.visible');
    cy.get('[data-testid="cvv-input"]').should('be.visible');
    cy.get('[data-testid="billing-zip-input"]').should('be.visible');
    cy.get('[data-testid="place-order-button"]').should('be.visible');

    // Verify vertical stacking by checking element positions
    cy.get('[data-testid="email-input"]').then(($email) => {
      const emailTop = $email[0].getBoundingClientRect().top;
      cy.get('[data-testid="first-name-input"]').then(($firstName) => {
        const firstNameTop = $firstName[0].getBoundingClientRect().top;
        expect(firstNameTop).to.be.greaterThan(emailTop);
      });
    });

    cy.get('[data-testid="first-name-input"]').then(($firstName) => {
      const firstNameBottom = $firstName[0].getBoundingClientRect().bottom;
      cy.get('[data-testid="last-name-input"]').then(($lastName) => {
        const lastNameTop = $lastName[0].getBoundingClientRect().top;
        expect(lastNameTop).to.be.greaterThan(firstNameBottom);
      });
    });

    // Fill out form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="first-name-input"]').type('John');
    cy.get('[data-testid="last-name-input"]').type('Doe');
    cy.get('[data-testid="address-input"]').type('123 Main St');
    cy.get('[data-testid="phone-input"]').type('555-123-465');
    cy.get('[data-testid="card-number-input"]').type('1111111111111111');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="billing-zip-input"]').type('12346');

    // Submit form
    cy.get('[data-testid="place-order-button"]').click();
    cy.wait('@checkoutSubmit');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Order placed successfully');
  });

  it('should handle form submission with validation errors on mobile', () => {
    // Set mobile viewport
    cy.viewport('iphone-12');

    // Verify form fields are visible
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="first-name-input"]').should('be.visible');
    cy.get('[data-testid="last-name-input"]').should('be.visible');
    cy.get('[data-testid="address-input"]').should('be.visible');
    cy.get('[data-testid="phone-input"]').should('be.visible');
    cy.get('[data-testid="card-number-input"]').should('be.visible');
    cy.get('[data-testid="cvv-input"]').should('be.visible');
    cy.get('[data-testid="billing-zip-input"]').should('be.visible');
    cy.get('[data-testid="place-order-button"]').should('be.visible');

    // Attempt to submit with missing required fields
    cy.get('[data-testid="place-order-button"]').click();

    // Verify validation error messages appear
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('contain', 'Email is required');
    cy.get('[data-testid="first-name-error"]').should('be.visible');
    cy.get('[data-testid="first-name-error"]').should('contain', 'First name is required');
    cy.get('[data-testid="last-name-error"]').should('be.visible');
    cy.get('[data-testid="last-name-error"]').should('contain', 'Last name is required');

    // Verify form is still vertically stacked and not hidden
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="first-name-input"]').should('be.visible');
    cy.get('[data-testid="last-name-input"]').should('be.visible');

    // Verify form is not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');
    cy.get('[data-testid="error-summary"]').should('be.visible');
    cy.get('[data-testid="error-summary"]').should('contain', 'Please fill out all required fields');
  });
});
